import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const dir = dirname(fileURLToPath(import.meta.url));
const screensDir = join(dir, 'screens');
const docsDir = join(dir, 'docs');
mkdirSync(screensDir, { recursive: true });
mkdirSync(docsDir, { recursive: true });

const ui = (pattern, navigation, purpose, primaryAction, density = 'medium', states) => ({
  pattern,
  navigation,
  purpose,
  primaryAction,
  hierarchy: {
    primary: purpose,
    secondary: 'Контекст, состояние и безопасный следующий шаг',
  },
  states: states || ({
    auth: ['default', 'loading', 'error'],
    collection: ['default', 'empty'],
    detail: ['default'],
    task: ['default', 'error'],
    player: ['default', 'loading', 'error'],
    capture: ['default', 'denied'],
    editor: ['default', 'error', 'success'],
    settings: ['default'],
    state: ['default'],
    system: ['default'],
  }[pattern]),
  density,
  contentCases: [
    { kind: 'typical', example: `${purpose}: партия K-184, 36 кадров и статус 18:40` },
    { kind: 'stress', example: 'Длинное имя автора, несколько статусов и плотный список' },
    { kind: 'failure', example: 'Нет сети, пустой результат или отказ в доступе' },
  ],
});

const permission = (key, plist, title, text, feature, gesture, screen, target, fallback, grounding, extra = {}) => ({
  key,
  plist,
  alert: { title, text },
  feature,
  gesture,
  screen,
  target,
  fallback,
  snack: fallback,
  risk: extra.risk || 'low',
  anchor: Boolean(extra.anchor),
  conditional: Boolean(extra.conditional),
  grounding,
  ...(extra.activate ? { activate: true } : {}),
  ...(extra.requires ? { requires: extra.requires } : {}),
  ...(extra.reviewNote ? { reviewNote: extra.reviewNote } : {}),
});

